import React from 'react'
import IconButton from '@mui/material/IconButton';
import QuestionMarkIcon from '@mui/icons-material/QuestionMark';import Swal from 'sweetalert2'
import { useState } from 'react'
export default function Popup() {
    const fireAlert = () => {
        Swal.fire({
            target: document.getElementById('form-modal'),
            title: 'Are Groceries really that much more expensive Nowadays?',
            text: 'Using the internet archive, I scraped thousands of website snapshots from a popular online retailer to gather as much historical pricing data as I could find. This website represents the culmination of hundreds of thousands of product prices from as early as 2015',
            showConfirmButton: true,
            confirmButtonText: "OK",
        }
        )
    }
    return (
        <div >
            
                <IconButton sx={{color: 'white'}}
                    
                    onClick={fireAlert}>
                    <QuestionMarkIcon/>
                </IconButton>

        </div>
    )
}
