import React, { useState, useEffect } from 'react';
import {ListItemText, List, ListItem, ListItemIcon} from '@mui/material';
import Divider from '@mui/material/Divider';
import TextField from '@mui/material/TextField';

export default function SearchBar(props) {
  const [filteredSuggestions, setFilteredSuggestions] = useState([{
    Name: '',
    Prod: '',
    Small: ''
  }]);
  const [inputValue, setInputValue] = useState('');
  const [data, setData] = useState('');
  const [dataToSend, setDataToSend] = useState(null);

  useEffect(() => {
    fetch('toBeUsed/entireSet.json')
    .then(response => response.json())
    .then(data => setData(data))
    .catch(error => console.error('Error fetching data:', error));
}, []);
if (!data) {
    return <div>Loading...</div>;
  } 
  const arrayColumn = (arr, n) => arr.map(x => x[n]);  
  
  const suggestion = data
  const handleChange = (event) => {
    const inputValue = event.target.value;
    setInputValue(inputValue);
    // Filter suggestions based on input value
    const filteredSuggestions = suggestion.filter(suggestions =>

      suggestions.id.toLowerCase().includes(inputValue.toLowerCase())
      
    );
    setFilteredSuggestions(filteredSuggestions.slice(0, 15));
  };

  const HandleClick = (params) => {
    console.log(props.props)

    console.log(params)
    props.props([params['id'], params['Date'], params['Price'], params['New Price']])


    // setInputValue(value);
    // setFilteredSuggestions([]);
  };

  return (
    <div className="autocomplete-co ntainer" place-items='anchor-center'>
      <TextField 
      id="outlined"    
      value={inputValue}
      placeholder="Type to search..." 
      onChange={handleChange} 
      variant="outlined"
      sx={{paddingDown:'30px', paddingTop:'20px', paddingX:'15%', width:'100%'}} />

        <List
          sx={{ width: '100%', bgcolor: 'background.paper' }}
          aria-labelledby="nested-list-subheader"
        >
        {filteredSuggestions.map((suggestion, index) => (
          <div>
           <ListItem id={index} onClick={() => HandleClick(suggestion)}>
            <ListItemText primary={suggestion.id} sx={{ paddingLeft: '3%', width: '100%' }} />
          
          </ListItem>
                <Divider sx={{ bgcolor: '#d1d8e1' }} />
                </div>
        ))}
        </List>
        
    </div>
  );
};
