import * as React from 'react';
import { LineChart } from '@mui/x-charts/LineChart';
import { useEffect, useState } from 'react';
import dayjs from "dayjs";
export default function Graph(props:props) {



  if (props.props[1] == 2) {
  let dateArr = props.props[0][1]
  const arrayColumn = (arr, n) => arr.map(x => x / 500);
  let array_2 = []

  for(var i = 0, length = dateArr.length; i < length; i++){
    const result = new Date(1970,0, 1, 0, 0, 0, 0);
    result.setDate(result.getDate() + dateArr[i])
    array_2.push(result)
  }

  return (
    <div 
    style={{width: '23vw', minWidth:'250pt', height:'30vh', minHeight:'250pt'}}>
    <LineChart 
    xAxis={[
      {
        label: "Date",
        data: array_2,
        scaleType: "time",
        valueFormatter: (date) => dayjs(date).format("MM YYYY"),
      },
    ]}
    yAxis={[{ label: "Product Price ($)", 
      valueFormatter: (value?: number) => {
              return `${value.toLocaleString()}$`

    },
  width: 200}]}
      series={[
        {
          data:props.props[0][props.props[1]], label: props.props[0][0]
        },
      ]}

    />
    </div>
  );
} else if (props.props[1] == 3) {
  let dateArr = props.props[0][1]
  const arrayColumn = (arr, n) => arr.map(x => x / 500);
  let array_2 = []

  for(var i = 0, length = dateArr.length; i < length; i++){
    const result = new Date(1970,0, 1, 0, 0, 0, 0);
    result.setDate(result.getDate() + dateArr[i])
    array_2.push(result)
  }

  
  return (
    <div 
    style={{width: '22vw', minWidth:'250pt', height:'30vh', minHeight:'250pt'}}>
    <LineChart 
    xAxis={[
      {
        label: "Date",
        data: array_2,
        scaleType: "time",
        valueFormatter: (date) => dayjs(date).format("MM YYYY"),
      },
    ]}
    yAxis={[{ 
      label: "Index 1982-1984 = 100", 

    }
     ]}
      series={[
        {
          data:props.props[0][0], label: 'Adjusted Product Price'
        },
        {
          data:props.props[0][2], label: 'Consumer Price Index'
        }
      ]}

    />
        </div>

  );
}}