// @ts-nocheck
import * as React from 'react';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';

function createData(
  key: number,
  price: string,
  dateRecorded: number,
  percentIncrease: string,
  percentIncreasePerYear: string
) {
  return { key, price, dateRecorded, percentIncrease, percentIncreasePerYear };
}


export default function BasicTable(props) {
    const rows = []
    
    // const lastPrice = rops.props[2]
    for (var i =0; i < props.props[2].length; i++) {       
        let percIncrease = '0.0' 
        let percentIncreasePerYear = '0.0'
        let withPrice = props.props[2][i]
        let result = new Date(1970,0, 1, 0, 0, 0, 0);
        result.setDate(result.getDate() +props.props[1][i])
        if (i >=1){        
          let diffDate = (result - rows.at(i-1)?.dateRecorded) / 31536000000
          let lastPrice =  rows.at(i-1)?.price
          percIncrease = ((((withPrice - lastPrice) / lastPrice) * 100).toFixed(1)).toString()
          percentIncreasePerYear = (percIncrease / diffDate).toFixed(1).toString()
          // percDiff = ((100 * Math.abs( (withPrice - lastPrice) / ( (withPrice+lastPrice)/2 ) )).toFixed(2)).toString()
        }
        // let percentPriceChangePerYear
        rows.push(createData(i, withPrice, result, percIncrease, percentIncreasePerYear))
    }
    console.log(rows)
  return (
    <TableContainer sx={{ minWidth: 600, maxHeight:'30vh'}} component={Paper}>
      <Table stickyHeader  sx={{ minWidth: 600, maxWidth: '50vw', maxHeight:'10vw'}}>
        <TableHead>
          <TableRow>
          <TableCell align="center">Date Recorded</TableCell>
          <TableCell align="center">Product Price</TableCell>
          <TableCell align="center">Percent Price Increase </TableCell>
          <TableCell align="center">Percent Price Increase per Year </TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {rows.map((row) => (
            <TableRow
              key={row.key}
            >
              <TableCell align="center" scope="row">
                {row.dateRecorded.toDateString().slice(4)}
              </TableCell>
              <TableCell align="center">{'$' + row.price}</TableCell>
              <TableCell align="center">{row.percentIncrease+'%'}</TableCell>
              <TableCell align="center">{row.percentIncreasePerYear+'% / Year'}</TableCell>

            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>

  );
}